    isAgiKiter = (((lw_get(profile, 'buildType') == BUILD_AGILITY) or (agi >= 400)))
    isMagicKiter = (((((mag >= 180) and hasPoison) and (str < 250)) and (lw_get(profile, 'buildType') != BUILD_HYBRID)))
    lw_put(profile, 'isKiter', (isAgiKiter or isMagicKiter))
