def detectBossFight():
    entities = getAliveEnemies()
    for eid in lw_values(entities):
        entityType = getName(eid)
        if ((entityType == "graal") or (entityType == "fennel_king")):
            return True
    return False

def initBossContext():
    global _isBossFight
    _isBossFight = True
    updateBossContext()

def updateBossContext():
    global _bossCombatLatched, _bossPhase, _bossTargetEID, _crystalMap, _graalCell, _graalEntity, _graalID, _graalX, _graalY, _myAssignedCrystal, _puzzleRole, _puzzleSolverID
    if (not _isBossFight):
        return None
    _graalEntity = None
    _graalCell = (-1)
    _graalX = 0
    _graalY = 0
    _crystalMap = {}
    allEntities = []
    enemies = getAliveEnemies()
    for eid in lw_values(enemies):
        push(allEntities, eid)
    allies = getAliveAllies()
    for aid in lw_values(allies):
        push(allEntities, aid)
    for eid in lw_values(allEntities):
        entityType = getName(eid)
        cellId = getCell(eid)
        if (entityType == "graal"):
            _graalID = eid
            if ((cellId == None) or (cellId < 0)):
                continue
            gLife = getLife(eid)
            if ((gLife == None) or (gLife <= 0)):
                continue
            if (not isAlive(eid)):
                continue
            _graalEntity = {'id': eid, 'cell': cellId, 'x': getCellX(cellId), 'y': getCellY(cellId)}
            _graalCell = cellId
            _graalX = getCellX(cellId)
            _graalY = getCellY(cellId)
        else:
            if ((((entityType == "red_crystal") or (entityType == "blue_crystal")) or (entityType == "yellow_crystal")) or (entityType == "green_crystal")):
                color = substring(entityType, 0, indexOf(entityType, "_"))
                goalAxis = getGoalAxis(color)
                lw_put(_crystalMap, eid, {'id': eid, 'color': color, 'goalAxis': goalAxis, 'cell': cellId, 'x': getCellX(cellId), 'y': getCellY(cellId), 'solved': False})
    if ((_graalEntity != None) and (_graalID != (-1))):
        if (not isAlive(_graalID)):
            _graalEntity = None
            _graalCell = (-1)
            _graalX = 0
            _graalY = 0
    if (((not _bossCombatLatched) and (_graalEntity != None)) and (getTurn() > 1)):
        if (not armyHasDivineProtection()):
            _graalEntity = None
            _graalCell = (-1)
            _graalX = 0
            _graalY = 0
    if _bossCombatLatched:
        _bossPhase = "COMBAT"
    else:
        if (_graalEntity != None):
            _bossPhase = "PUZZLE"
        else:
            _bossPhase = "COMBAT"
            if (_graalID != (-1)):
                _bossCombatLatched = True
    if (_bossPhase == "PUZZLE"):
        assignPuzzleRoles()
        if (_puzzleRole == "SOLVER"):
            assignSolverCrystal()
        else:
            _myAssignedCrystal = None
            _bossTargetEID = None
            clearCrystalScalars()
    else:
        _puzzleRole = None
        _puzzleSolverID = (-1)
        _myAssignedCrystal = None
        _bossTargetEID = None
        clearCrystalScalars()

def getBossPhase():
    return _bossPhase

def armyHasDivineProtection():
    enemies = getAliveEnemies()
    armySeen = False
    for eid in lw_values(enemies):
        n = getName(eid)
        if ((n == "graal") or (indexOf(n, "crystal") != (-1))):
            continue
        armySeen = True
        effs = getEffects(eid)
        if (effs == None):
            continue
        for e in lw_values(effs):
            if (lw_get(e, 0) == 59):
                return True
    if (not armySeen):
        return True
    return False

def syncCrystalScalars(crystal):
    global _myCrystalCell, _myCrystalColor, _myCrystalGoalAxis, _myCrystalSolved, _myCrystalX, _myCrystalY
    _myCrystalCell = lw_get(crystal, 'cell')
    _myCrystalX = lw_get(crystal, 'x')
    _myCrystalY = lw_get(crystal, 'y')
    _myCrystalColor = lw_get(crystal, 'color')
    _myCrystalGoalAxis = lw_get(crystal, 'goalAxis')
    _myCrystalSolved = lw_get(crystal, 'solved')

def clearCrystalScalars():
    global _myCrystalCell, _myCrystalColor, _myCrystalGoalAxis, _myCrystalSolved, _myCrystalX, _myCrystalY
    _myCrystalCell = (-1)
    _myCrystalX = 0
    _myCrystalY = 0
    _myCrystalColor = None
    _myCrystalGoalAxis = None
    _myCrystalSolved = False

def isCellSolvedForAxis(cell, goalAxis):
    if (((_graalCell == (-1)) or (cell == None)) or (cell < 0)):
        return False
    cx = getCellX(cell)
    cy = getCellY(cell)
    if (not checkOnAxis(cx, cy, _graalX, _graalY, goalAxis)):
        return False
    return lineOfSight(cell, _graalCell, allAliveEntities())

def allAliveEntities():
    ids = [getEntity()]
    enemies = getAliveEnemies()
    for e in lw_values(enemies):
        push(ids, e)
    allies = getAliveAllies()
    for a in lw_values(allies):
        push(ids, a)
    return ids

def allyHasChip(eid, chipId):
    cd = getCooldown(chipId, eid)
    return (cd != None)

def isNamedSolver(name):
    return ((name == "AdaLovelace") or (name == "KurtGodel"))

def assignPuzzleRoles():
    global _puzzleRole, _puzzleSolverID, _pzPartnerSolverID, _pzSolverEverSeen
    if (_bossPhase != "PUZZLE"):
        _puzzleRole = None
        _puzzleSolverID = (-1)
        _pzPartnerSolverID = (-1)
        return None
    myID = getEntity()
    allAllies = [myID]
    allies = getAliveAllies()
    for aid in lw_values(allies):
        push(allAllies, aid)
    if (count(allAllies) <= 1):
        _puzzleRole = "SOLVER"
        _puzzleSolverID = myID
        _pzPartnerSolverID = (-1)
        return None
    solverIDs = []
    for aid in lw_values(allAllies):
        if isNamedSolver(getName(aid)):
            push(solverIDs, aid)
    if (count(solverIDs) > 0):
        _pzSolverEverSeen = True
    if ((count(solverIDs) == 0) and (not _pzSolverEverSeen)):
        push(solverIDs, lw_get(allAllies, 0))
    iAmListed = False
    for sid in lw_values(solverIDs):
        if (sid == myID):
            iAmListed = True
    iHaveChips = ((allyHasChip(myID, CHIP_GRAPPLE) or allyHasChip(myID, CHIP_BOXING_GLOVE)) or allyHasChip(myID, CHIP_INVERSION))
    if (iAmListed and ((iHaveChips or (count(allAllies) == 1)))):
        _puzzleRole = "SOLVER"
        _puzzleSolverID = myID
        _pzPartnerSolverID = (-1)
        for sid2 in lw_values(solverIDs):
            if (sid2 != myID):
                _pzPartnerSolverID = sid2
        return None
    _pzPartnerSolverID = (-1)
    if (count(solverIDs) == 0):
        _puzzleRole = "SUPPORT"
        _puzzleSolverID = (-1)
        return None
    supports = []
    for aid2 in lw_values(allAllies):
        isSol = False
        for sid3 in lw_values(solverIDs):
            if (sid3 == aid2):
                isSol = True
        if (not isSol):
            push(supports, aid2)
    sort(supports)
    sort(solverIDs)
    myIdx = 0
    i = 0
    while (i < count(supports)):
        if (lw_get(supports, i) == myID):
            myIdx = i
        i = lw_add(i, 1)
    _puzzleSolverID = lw_get(solverIDs, lw_mod(myIdx, count(solverIDs)))
    _puzzleRole = ("BUFFER" if (getName(myID) == "KurtGodel") else "SUPPORT")

def assignSolverCrystal():
    global _bossTargetEID, _myAssignedCrystal
    myCell = getCell()
    bestDist = 999
    bestEID = None
    for eid in lw_values(mapKeys(_crystalMap)):
        cData = lw_get(_crystalMap, eid)
        if isCrystalSolved(cData):
            continue
        d = getCellDistance(myCell, lw_get(cData, 'cell'))
        if (d < bestDist):
            bestDist = d
            bestEID = eid
    if (bestEID != None):
        _myAssignedCrystal = lw_get(_crystalMap, bestEID)
        _bossTargetEID = bestEID
        syncCrystalScalars(lw_get(_crystalMap, bestEID))
    else:
        _myAssignedCrystal = None
        _bossTargetEID = None
        clearCrystalScalars()

def nearestUnsolvedCrystalTo(cell, excludeEID):
    best = None
    bestD = 9999
    for eid in lw_values(mapKeys(_crystalMap)):
        if (eid == excludeEID):
            continue
        cData = lw_get(_crystalMap, eid)
        if isCrystalSolved(cData):
            continue
        cc = getCell(eid)
        if ((cc == None) or (cc < 0)):
            continue
        d = getCellDistance(cell, cc)
        if ((d != None) and (d < bestD)):
            bestD = d
            best = eid
    return best

def readPartnerClaim():
    global _pzPartnerClaimEID
    if (_pzPartnerSolverID == (-1)):
        _pzPartnerClaimEID = None
        return None
    msgs = getMessages()
    for m in lw_values(msgs):
        if (getMessageAuthor(m) != _pzPartnerSolverID):
            continue
        if (getMessageType(m) != MESSAGE_CUSTOM):
            continue
        p = getMessageParams(m)
        if (((p != None) and (count(p) == 2)) and (lw_get(p, 0) == PZ_MSG_FOCUS)):
            _pzPartnerClaimEID = lw_get(p, 1)

def announceFocus(eid):
    if ((_pzPartnerSolverID != (-1)) and (eid != None)):
        sendAll(MESSAGE_CUSTOM, [PZ_MSG_FOCUS, eid])

def pickFocusCrystal(myCell):
    global _pzFocusEID
    myID = getEntity()
    partner = _pzPartnerSolverID
    partnerAlive = ((partner != (-1)) and isAlive(partner))
    partnerPick = None
    if partnerAlive:
        readPartnerClaim()
        if (_pzPartnerClaimEID != None):
            pc = lw_get(_crystalMap, _pzPartnerClaimEID)
            if ((pc != None) and (not isCrystalSolved(pc))):
                partnerPick = _pzPartnerClaimEID
        if (partnerPick == None):
            partnerPick = nearestUnsolvedCrystalTo(getCell(partner), None)
            if (partnerPick == _pzFocusEID):
                partnerPick = None
    if ((_pzFocusEID != None) and (_pzFocusEID != partnerPick)):
        fc = lw_get(_crystalMap, _pzFocusEID)
        if ((fc != None) and (not isCrystalSolved(fc))):
            announceFocus(_pzFocusEID)
            return _pzFocusEID
    mine = nearestUnsolvedCrystalTo(myCell, partnerPick)
    if ((mine == None) and (partnerPick != None)):
        mine = partnerPick
    _pzFocusEID = mine
    announceFocus(mine)
    return _pzFocusEID

def pickNearestUnsolvedCrystal(myCell):
    bestDist = 999
    bestEID = None
    for eid in lw_values(mapKeys(_crystalMap)):
        cData = lw_get(_crystalMap, eid)
        cCell = lw_get(cData, 'cell')
        if isCellSolvedForAxis(cCell, lw_get(cData, 'goalAxis')):
            continue
        d = getCellDistance(myCell, cCell)
        if (d < bestDist):
            bestDist = d
            bestEID = eid
    return bestEID

def getGoalAxis(color):
    if (color == "red"):
        return "south"
    if (color == "blue"):
        return "east"
    if (color == "yellow"):
        return "west"
    if (color == "green"):
        return "north"
    return "unknown"

def isOnGoalAxis(crystal):
    if (_graalCell == (-1)):
        return False
    axis = lw_get(crystal, 'goalAxis')
    cx = lw_get(crystal, 'x')
    cy = lw_get(crystal, 'y')
    gx = _graalX
    gy = _graalY
    if (axis == "north"):
        return ((cx == gx) and (cy < gy))
    else:
        if (axis == "south"):
            return ((cx == gx) and (cy > gy))
        else:
            if (axis == "east"):
                return ((cy == gy) and (cx > gx))
            else:
                if (axis == "west"):
                    return ((cy == gy) and (cx < gx))
    return False

def hasLOSToGraal(crystal):
    if (_graalCell == (-1)):
        return False
    return lineOfSight(lw_get(crystal, 'cell'), _graalCell, allAliveEntities())

def isCrystalSolved(crystal):
    return isCellSolvedForAxis(lw_get(crystal, 'cell'), lw_get(crystal, 'goalAxis'))

def getDistanceToAxis(ignoredCrystal):
    if (_graalCell == (-1)):
        return 999
    axis = _myCrystalGoalAxis
    cx = _myCrystalX
    cy = _myCrystalY
    gx = _graalX
    gy = _graalY
    if ((axis == "north") or (axis == "south")):
        return abs(lw_sub(cx, gx))
    else:
        return abs(lw_sub(cy, gy))

def getDirectionToSlide(ignoredCrystal):
    if (_graalCell == (-1)):
        return None
    axis = _myCrystalGoalAxis
    cx = _myCrystalX
    cy = _myCrystalY
    gx = _graalX
    gy = _graalY
    if ((axis == "north") or (axis == "south")):
        if (cx < gx):
            return "pull"
        if (cx > gx):
            return "push"
        if ((axis == "north") and (cy >= gy)):
            return "push"
        if ((axis == "south") and (cy <= gy)):
            return "pull"
    else:
        if (cy < gy):
            return "pull"
        if (cy > gy):
            return "push"
        if ((axis == "east") and (cx <= gx)):
            return "pull"
        if ((axis == "west") and (cx >= gx)):
            return "push"
    return None

def getTargetAxisCell(ignoredCrystal):
    if (_graalCell == (-1)):
        return (-1)
    axis = _myCrystalGoalAxis
    gx = _graalX
    gy = _graalY
    tx = gx
    ty = gy
    if (axis == "south"):
        ty = lw_add(gy, 1)
    else:
        if (axis == "north"):
            ty = lw_sub(gy, 1)
        else:
            if (axis == "east"):
                tx = lw_add(gx, 1)
            else:
                if (axis == "west"):
                    tx = lw_sub(gx, 1)
    cell = getCellFromXY(tx, ty)
    if ((cell != None) and (not isObstacle(cell))):
        return cell
    d = 2
    while (d <= 8):
        sx = gx
        sy = gy
        if (axis == "south"):
            sy = lw_add(gy, d)
        else:
            if (axis == "north"):
                sy = lw_sub(gy, d)
            else:
                if (axis == "east"):
                    sx = lw_add(gx, d)
                else:
                    if (axis == "west"):
                        sx = lw_sub(gx, d)
        scanCell = getCellFromXY(sx, sy)
        if (((scanCell != None) and (not isObstacle(scanCell))) and lineOfSight(scanCell, _graalCell, allAliveEntities())):
            return scanCell
        d = lw_add(d, 1)
    return (-1)

def computePullDirection(cx, cy, playerCell):
    px = getCellX(playerCell)
    py = getCellY(playerCell)
    dx = 0
    dy = 0
    if (px < cx):
        dx = (-1)
    else:
        if (px > cx):
            dx = 1
    if (py < cy):
        dy = (-1)
    else:
        if (py > cy):
            dy = 1
    return [dx, dy]

def computePushDirection(cx, cy, playerCell):
    px = getCellX(playerCell)
    py = getCellY(playerCell)
    dx = 0
    dy = 0
    if (px < cx):
        dx = 1
    else:
        if (px > cx):
            dx = (-1)
    if (py < cy):
        dy = 1
    else:
        if (py > cy):
            dy = (-1)
    return [dx, dy]

def computeAxisDist(cx, cy, gx, gy, goalAxis):
    if ((goalAxis == "north") or (goalAxis == "south")):
        return abs(lw_sub(cx, gx))
    else:
        return abs(lw_sub(cy, gy))

def checkOnAxis(cx, cy, gx, gy, goalAxis):
    if (goalAxis == "north"):
        return ((cx == gx) and (cy < gy))
    if (goalAxis == "south"):
        return ((cx == gx) and (cy > gy))
    if (goalAxis == "east"):
        return ((cy == gy) and (cx > gx))
    if (goalAxis == "west"):
        return ((cy == gy) and (cx < gx))
    return False

def computeCrystalFinalDest():
    axis = _myCrystalGoalAxis
    gx = _graalX
    gy = _graalY
    if (axis == "north"):
        return getCellFromXY(gx, lw_sub(gy, 1))
    if (axis == "south"):
        return getCellFromXY(gx, lw_add(gy, 1))
    if (axis == "east"):
        return getCellFromXY(lw_add(gx, 1), gy)
    if (axis == "west"):
        return getCellFromXY(lw_sub(gx, 1), gy)
    return None

def computeCrystalAxisDest():
    axis = _myCrystalGoalAxis
    if ((axis == "north") or (axis == "south")):
        return getCellFromXY(_graalX, _myCrystalY)
    else:
        return getCellFromXY(_myCrystalX, _graalY)

def isCrystalOnAxis():
    axis = _myCrystalGoalAxis
    if (axis == "north"):
        return ((_myCrystalX == _graalX) and (_myCrystalY < _graalY))
    if (axis == "south"):
        return ((_myCrystalX == _graalX) and (_myCrystalY > _graalY))
    if (axis == "east"):
        return ((_myCrystalY == _graalY) and (_myCrystalX > _graalX))
    if (axis == "west"):
        return ((_myCrystalY == _graalY) and (_myCrystalX < _graalX))
    return False

def findIdealSlideCell(ignoredCrystal, direction, playerCell):
    if ((_myCrystalCell == (-1)) or (_graalCell == (-1))):
        return (-1)
    axis = _myCrystalGoalAxis
    cx = _myCrystalX
    cy = _myCrystalY
    moveAxis = ("x" if (((axis == "north") or (axis == "south"))) else "y")
    delta = ((lw_sub(_graalX, cx)) if ((moveAxis == "x")) else (lw_sub(_graalY, cy)))
    absDelta = abs(delta)
    sign = (1 if ((delta > 0)) else (-1))
    if (direction == "pull"):
        destX = (_graalX if ((moveAxis == "x")) else cx)
        destY = (_graalY if ((moveAxis == "y")) else cy)
        maxD = lw_sub(8, absDelta)
        d = 1
        while (d <= maxD):
            tx = destX
            ty = destY
            if (moveAxis == "x"):
                tx = lw_add(destX, lw_mul(sign, d))
            else:
                ty = lw_add(destY, lw_mul(sign, d))
            cell = getCellFromXY(tx, ty)
            if (cell == None):
                d = lw_add(d, 1)
                continue
            if isObstacle(cell):
                d = lw_add(d, 1)
                continue
            if ((cell != playerCell) and isEntity(cell)):
                d = lw_add(d, 1)
                continue
            return cell
            d = lw_add(d, 1)
    else:
        d = 2
        while (d <= 8):
            tx = cx
            ty = cy
            if (moveAxis == "x"):
                tx = lw_sub(cx, lw_mul(sign, d))
            else:
                ty = lw_sub(cy, lw_mul(sign, d))
            cell = getCellFromXY(tx, ty)
            if (cell == None):
                d = lw_add(d, 1)
                continue
            if isObstacle(cell):
                d = lw_add(d, 1)
                continue
            if ((cell != playerCell) and isEntity(cell)):
                d = lw_add(d, 1)
                continue
            return cell
            d = lw_add(d, 1)
    return (-1)

def selectCombatTarget(fieldMapObj):
    enemies = getAliveEnemies()
    if (count(enemies) == 0):
        return None
    priority = ["fennel_king", "fennel_knight", "fennel_scribe", "fennel_squire"]
    for pName in lw_values(priority):
        for eid in lw_values(enemies):
            if (getName(eid) == pName):
                enemySub = fieldMapObj.getEnemySubMap()
                if mapContainsKey(enemySub, eid):
                    return lw_get(enemySub, eid)
    bestTarget = None
    bestHP = 999999
    for eid in lw_values(enemies):
        hp = getLife(eid)
        if (hp < bestHP):
            bestHP = hp
            bestTarget = eid
    if (bestTarget != None):
        enemySub = fieldMapObj.getEnemySubMap()
        if mapContainsKey(enemySub, bestTarget):
            return lw_get(enemySub, bestTarget)
    return None

def isCrystalEntity(eid):
    return mapContainsKey(_crystalMap, eid)

def bossDiag(myCell):
    g = "none"
    if (_graalID != (-1)):
        g = lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(_graalID, "/"), isAlive(_graalID)), "/"), getLife(_graalID)), "/"), getCell(_graalID))
    say(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add("B1 PH=", _bossPhase), " R="), _puzzleRole), " SID="), _puzzleSolverID), " EID="), _bossTargetEID), " me="), myCell), " G="), g))

def hasEntityBlockingLine(fromCell, toCell):
    dTotal = getCellDistance(fromCell, toCell)
    if ((dTotal == None) or (dTotal <= 1)):
        return False
    enemies = getAliveEnemies()
    for eid in lw_values(enemies):
        if (eid == _bossTargetEID):
            continue
        eCell = getCell(eid)
        if ((eCell == fromCell) or (eCell == toCell)):
            continue
        if (isOnSameLine(fromCell, eCell) and isOnSameLine(eCell, toCell)):
            d1 = getCellDistance(fromCell, eCell)
            d2 = getCellDistance(eCell, toCell)
            if (lw_add(d1, d2) == dTotal):
                return True
    allies = getAliveAllies()
    for aid in lw_values(allies):
        aCell = getCell(aid)
        if ((aCell == fromCell) or (aCell == toCell)):
            continue
        if (isOnSameLine(fromCell, aCell) and isOnSameLine(aCell, toCell)):
            d1 = getCellDistance(fromCell, aCell)
            d2 = getCellDistance(aCell, toCell)
            if (lw_add(d1, d2) == dTotal):
                return True
    return False

def diagNext(cell, step):
    next = lw_add(cell, step)
    if ((next < 0) or (next > 612)):
        return (-1)
    if (getCellDistance(cell, next) != 1):
        return (-1)
    return next

def walkDiag(startCell, step, numSteps):
    cell = startCell
    i = 0
    while (i < numSteps):
        cell = diagNext(cell, step)
        if (cell == (-1)):
            return (-1)
        i = lw_add(i, 1)
    return cell

def findBoxStand(crystalCell, step, myCell):
    pos = crystalCell
    firstStand = (-1)
    myCellValid = False
    k = 1
    while (k <= 8):
        next = diagNext(pos, (-lw_num(step)))
        if (next == (-1)):
            break
        pos = next
        if isObstacle(pos):
            break
        if ((pos != myCell) and isEntity(pos)):
            break
        if (k >= 2):
            if (firstStand == (-1)):
                firstStand = pos
            if (pos == myCell):
                myCellValid = True
                break
        k = lw_add(k, 1)
    if myCellValid:
        return myCell
    return firstStand

def findGrapStand(targetCell, step, crystalSteps, myCell):
    pos = targetCell
    firstStand = (-1)
    myCellValid = False
    j = 1
    while (j <= lw_sub(8, crystalSteps)):
        next = diagNext(pos, step)
        if (next == (-1)):
            break
        pos = next
        if isObstacle(pos):
            break
        if ((pos != myCell) and isEntity(pos)):
            break
        if (firstStand == (-1)):
            firstStand = pos
        if (pos == myCell):
            myCellValid = True
            break
        j = lw_add(j, 1)
    if myCellValid:
        return myCell
    return firstStand

def routeSlideStand(fromCell, destCell, step, slideLen, myCell):
    best = (-1)
    bestD = 9999
    pos = fromCell
    k = 1
    while (k <= lw_sub(8, slideLen)):
        nx = diagNext(pos, (-lw_num(step)))
        if (nx == (-1)):
            break
        pos = nx
        if isObstacle(pos):
            break
        if ((pos != myCell) and isEntity(pos)):
            break
        if (k < 2):
            k = lw_add(k, 1)
            continue
        d1 = getCellDistance(myCell, pos)
        if ((d1 != None) and (d1 < bestD)):
            bestD = d1
            best = pos
        k = lw_add(k, 1)
    pos = destCell
    k2 = 1
    while (k2 <= lw_sub(8, slideLen)):
        nx2 = diagNext(pos, step)
        if (nx2 == (-1)):
            break
        pos = nx2
        if isObstacle(pos):
            break
        if ((pos != myCell) and isEntity(pos)):
            break
        d2 = getCellDistance(myCell, pos)
        if ((d2 != None) and (d2 < bestD)):
            bestD = d2
            best = pos
        k2 = lw_add(k2, 1)
    return best

def routeEdgeChip(fromCell, destCell, step, slideLen, standCell):
    sx = getCellX(standCell)
    cx = getCellX(fromCell)
    dxs = getCellX(destCell)
    if ((sx == cx) and (sx == dxs)):
        sy = getCellY(standCell)
        cy = getCellY(fromCell)
        dy = getCellY(destCell)
        if ((((dy > cy) and (sy < cy))) or (((dy < cy) and (sy > cy)))):
            return CHIP_BOXING_GLOVE
        return CHIP_GRAPPLE
    if ((((dxs > cx) and (sx < cx))) or (((dxs < cx) and (sx > cx)))):
        return CHIP_BOXING_GLOVE
    return CHIP_GRAPPLE

def planCrystalRoute(crystalCell, goalAxis, myCell, allowInversion):
    steps = [18, (-18), 17, (-17)]
    routeArmyCells = puzzleArmyCells()
    queue = [crystalCell]
    visited = {}
    lw_put(visited, crystalCell, True)
    parentFrom = {}
    parentEdge = {}
    found = (-1)
    qi = 0
    while ((qi < count(queue)) and (count(queue) < 400)):
        cur = lw_get(queue, qi)
        qi = lw_add(qi, 1)
        if ((cur != crystalCell) and isCellSolvedForAxis(cur, goalAxis)):
            found = cur
            break
        si = 0
        while (si < 4):
            step = lw_get(steps, si)
            pos = cur
            d = 1
            while (d <= 8):
                nx = diagNext(pos, step)
                if (nx == (-1)):
                    break
                pos = nx
                if (isObstacle(pos) or (pos == _graalCell)):
                    break
                if (((pos != crystalCell) and (pos != myCell)) and isEntity(pos)):
                    break
                if (not mapContainsKey(visited, pos)):
                    stand = routeSlideStand(cur, pos, step, d, myCell)
                    if (stand != (-1)):
                        lw_put(visited, pos, True)
                        lw_put(parentFrom, pos, cur)
                        lw_put(parentEdge, pos, {'chip': routeEdgeChip(cur, pos, step, d, stand), 'target': pos, 'stand': stand, 'dest': pos})
                        push(queue, pos)
                d = lw_add(d, 1)
            if allowInversion:
                landingSafe = (nearestArmyDistFrom(cur, routeArmyCells) >= 4)
                ipos = cur
                d2 = 1
                while (d2 <= 14):
                    inx = diagNext(ipos, step)
                    if (inx == (-1)):
                        break
                    ipos = inx
                    if (isObstacle(ipos) or (ipos == _graalCell)):
                        break
                    if ((ipos != myCell) and isEntity(ipos)):
                        break
                    if (not mapContainsKey(visited, ipos)):
                        if (landingSafe or isCellSolvedForAxis(ipos, goalAxis)):
                            lw_put(visited, ipos, True)
                            lw_put(parentFrom, ipos, cur)
                            lw_put(parentEdge, ipos, {'chip': CHIP_INVERSION, 'target': (-1), 'stand': ipos, 'dest': ipos})
                            push(queue, ipos)
                    d2 = lw_add(d2, 1)
            si = lw_add(si, 1)
    if (found == (-1)):
        return None
    node = found
    while (lw_get(parentFrom, node) != crystalCell):
        node = lw_get(parentFrom, node)
    return lw_get(parentEdge, node)

def findBestChipMove(crystalCell, finalDest, myCell, grapUsed, boxUsed, excludeStep):
    crystalX = getCellX(crystalCell)
    crystalY = getCellY(crystalCell)
    fx = getCellX(finalDest)
    fy = getCellY(finalDest)
    dx = lw_sub(fx, crystalX)
    dy = lw_sub(fy, crystalY)
    curManhattan = lw_add(abs(dx), abs(dy))
    steps = [18, (-18), 17, (-17)]
    sdxs = [1, (-1), 0, 0]
    sdys = [0, 0, 1, (-1)]
    bestScore = (-999)
    bestStand = (-1)
    bestChip = None
    bestTarget = (-1)
    bestNavDist = 999
    bestStep = 0
    si = 0
    while (si < 4):
        step = lw_get(steps, si)
        sdx = lw_get(sdxs, si)
        sdy = lw_get(sdys, si)
        if ((excludeStep != 0) and (step == excludeStep)):
            si = lw_add(si, 1)
            continue
        maxClear = 0
        pos = crystalCell
        d = 1
        while (d <= 8):
            next = diagNext(pos, step)
            if (next == (-1)):
                break
            pos = next
            if isObstacle(pos):
                break
            if (pos == _graalCell):
                break
            if ((pos != finalDest) and isEntity(pos)):
                break
            maxClear = d
            d = lw_add(d, 1)
        if (maxClear == 0):
            si = lw_add(si, 1)
            continue
        bestD = 0
        bestImprove = (-999)
        d = 1
        while (d <= maxClear):
            newManhattan = lw_add(abs(lw_sub(dx, lw_mul(sdx, d))), abs(lw_sub(dy, lw_mul(sdy, d))))
            improve = lw_sub(curManhattan, newManhattan)
            if (improve > bestImprove):
                bestImprove = improve
                bestD = d
            d = lw_add(d, 1)
        if ((bestD == 0) or (bestImprove <= 0)):
            si = lw_add(si, 1)
            continue
        newCX = lw_add(crystalX, lw_mul(sdx, bestD))
        newCY = lw_add(crystalY, lw_mul(sdy, bestD))
        goalAxis = _myCrystalGoalAxis
        trapped = False
        if (((goalAxis == "north") and (newCX == _graalX)) and (newCY >= _graalY)):
            trapped = True
        if (((goalAxis == "south") and (newCX == _graalX)) and (newCY <= _graalY)):
            trapped = True
        if (((goalAxis == "east") and (newCY == _graalY)) and (newCX <= _graalX)):
            trapped = True
        if (((goalAxis == "west") and (newCY == _graalY)) and (newCX >= _graalX)):
            trapped = True
        if trapped:
            bestD = lw_sub(bestD, 1)
            if (bestD <= 0):
                si = lw_add(si, 1)
                continue
            bestImprove = lw_sub(curManhattan, (lw_add(abs(lw_sub(dx, lw_mul(sdx, bestD))), abs(lw_sub(dy, lw_mul(sdy, bestD))))))
            if (bestImprove <= 0):
                si = lw_add(si, 1)
                continue
            newCX = lw_add(crystalX, lw_mul(sdx, bestD))
            newCY = lw_add(crystalY, lw_mul(sdy, bestD))
        targetCell = lw_add(crystalCell, lw_mul(step, bestD))
        if (boxUsed < 4):
            boxStand = findBoxStand(crystalCell, step, myCell)
            if (boxStand != (-1)):
                dBox = getCellDistance(myCell, boxStand)
                if ((bestImprove > bestScore) or (((bestImprove == bestScore) and (dBox < bestNavDist)))):
                    bestScore = bestImprove
                    bestStand = boxStand
                    bestChip = CHIP_BOXING_GLOVE
                    bestTarget = targetCell
                    bestNavDist = dBox
                    bestStep = step
        if (grapUsed < 4):
            grapStand = findGrapStand(targetCell, step, bestD, myCell)
            if (grapStand != (-1)):
                dGrap = getCellDistance(myCell, grapStand)
                if ((bestImprove > bestScore) or (((bestImprove == bestScore) and (dGrap < bestNavDist)))):
                    bestScore = bestImprove
                    bestStand = grapStand
                    bestChip = CHIP_GRAPPLE
                    bestTarget = targetCell
                    bestNavDist = dGrap
                    bestStep = step
        si = lw_add(si, 1)
    if (bestStand == (-1)):
        return None
    return {'stand': bestStand, 'chip': bestChip, 'target': bestTarget, 'score': bestScore, 'step': bestStep}

def hasImprovingPath(fromCell, finalDest, excludeStep):
    fromX = getCellX(fromCell)
    fromY = getCellY(fromCell)
    fx = getCellX(finalDest)
    fy = getCellY(finalDest)
    curManhattan = lw_add(abs(lw_sub(fx, fromX)), abs(lw_sub(fy, fromY)))
    steps = [18, (-18), 17, (-17)]
    sdxs = [1, (-1), 0, 0]
    sdys = [0, 0, 1, (-1)]
    si = 0
    while (si < 4):
        step = lw_get(steps, si)
        if ((excludeStep != 0) and (step == excludeStep)):
            si = lw_add(si, 1)
            continue
        next = diagNext(fromCell, step)
        if (next == (-1)):
            si = lw_add(si, 1)
            continue
        if isObstacle(next):
            si = lw_add(si, 1)
            continue
        if (next == _graalCell):
            si = lw_add(si, 1)
            continue
        newManhattan = lw_add(abs(lw_sub(lw_sub(fx, fromX), lw_get(sdxs, si))), abs(lw_sub(lw_sub(fy, fromY), lw_get(sdys, si))))
        if (newManhattan < curManhattan):
            return True
        si = lw_add(si, 1)
    return False

def findDetourMove(crystalCell, finalDest, myCell, grapUsed, boxUsed, excludeStep):
    steps = [18, (-18), 17, (-17)]
    bestStand = (-1)
    bestChip = None
    bestTarget = (-1)
    bestNavDist = 999
    bestStep = 0
    si = 0
    while (si < 4):
        step = lw_get(steps, si)
        if ((excludeStep != 0) and (step == excludeStep)):
            si = lw_add(si, 1)
            continue
        next = diagNext(crystalCell, step)
        if (next == (-1)):
            si = lw_add(si, 1)
            continue
        if isObstacle(next):
            si = lw_add(si, 1)
            continue
        if (next == _graalCell):
            si = lw_add(si, 1)
            continue
        if isEntity(next):
            si = lw_add(si, 1)
            continue
        if (not hasImprovingPath(next, finalDest, (-lw_num(step)))):
            si = lw_add(si, 1)
            continue
        if (boxUsed < 4):
            boxStand = findBoxStand(crystalCell, step, myCell)
            if (boxStand != (-1)):
                dBox = getCellDistance(myCell, boxStand)
                if ((bestStand == (-1)) or (dBox < bestNavDist)):
                    bestStand = boxStand
                    bestChip = CHIP_BOXING_GLOVE
                    bestTarget = next
                    bestNavDist = dBox
                    bestStep = step
        if (grapUsed < 4):
            grapStand = findGrapStand(next, step, 1, myCell)
            if (grapStand != (-1)):
                dGrap = getCellDistance(myCell, grapStand)
                if ((bestStand == (-1)) or (dGrap < bestNavDist)):
                    bestStand = grapStand
                    bestChip = CHIP_GRAPPLE
                    bestTarget = next
                    bestNavDist = dGrap
                    bestStep = step
        si = lw_add(si, 1)
    if (bestStand == (-1)):
        return None
    return {'stand': bestStand, 'chip': bestChip, 'target': bestTarget, 'score': 0, 'step': bestStep}

def getEnclaveCells():
    visited = {}
    queue = [_graalCell]
    lw_put(visited, _graalCell, True)
    for ceid in lw_values(mapKeys(_crystalMap)):
        cCell = lw_get(lw_get(_crystalMap, ceid), 'cell')
        lw_put(visited, cCell, True)
    idx = 0
    while (idx < count(queue)):
        cell = lw_get(queue, idx)
        idx = lw_add(idx, 1)
        steps = [17, (-17), 18, (-18)]
        for s in lw_values(steps):
            next = lw_add(cell, s)
            if ((next < 0) or (next > 612)):
                continue
            if mapContainsKey(visited, next):
                continue
            if (getCellDistance(cell, next) != 1):
                continue
            if isObstacle(next):
                continue
            lw_put(visited, next, True)
            push(queue, next)
    return queue

def findNearestEnclaveCell(myCell):
    enclave = getEnclaveCells()
    bestCell = (-1)
    bestDist = 999
    for cell in lw_values(enclave):
        d = getCellDistance(myCell, cell)
        if (d < bestDist):
            bestDist = d
            bestCell = cell
    return bestCell

def findTeleportTarget(crystalCell, myCell):
    queue = getEnclaveCells()
    bestCell = (-1)
    bestDist = 999
    for cell in lw_values(queue):
        if isEntity(cell):
            continue
        dFromMe = getCellDistance(myCell, cell)
        if ((dFromMe < 1) or (dFromMe > 12)):
            continue
        dFromCrystal = getCellDistance(crystalCell, cell)
        if (dFromCrystal < bestDist):
            bestDist = dFromCrystal
            bestCell = cell
    return bestCell

def logMapLayout():
    obstacles = getObstacles()
    obsSet = {}
    for o in lw_values(obstacles):
        lw_put(obsSet, o, True)
    cellId = 0
    row = 0
    while (row < 35):
        rowSize = (18 if ((lw_mod(row, 2) == 0)) else 17)
        line = ""
        if (lw_mod(row, 2) != 0):
            line = lw_add(line, "   ")
        col = 0
        while (col < rowSize):
            if mapContainsKey(obsSet, cellId):
                line = lw_add(line, "  X  ")
            else:
                if (cellId < 10):
                    line = lw_add(line, lw_add(lw_add("  ", cellId), "  "))
                else:
                    if (cellId < 100):
                        line = lw_add(line, lw_add(lw_add(" ", cellId), "  "))
                    else:
                        line = lw_add(line, lw_add(lw_add(" ", cellId), " "))
            cellId = lw_add(cellId, 1)
            col = lw_add(col, 1)
        debug(line)
        row = lw_add(row, 1)

def executeBossCombatPoke():
    myID = getEntity()
    if ((getMagic() < 300) and (getStrength() < 300)):
        return False
    solverSurvival(myID)
    armyCells = puzzleArmyCells()
    if (count(armyCells) == 0):
        swatCrystals(myID)
        return False
    casted = 0
    if tryPoisonCast(myID, CHIP_PLAGUE, 5, 3, 6, 2, armyCells, False):
        casted = lw_add(casted, 1)
    if tryPoisonCast(myID, CHIP_TOXIN, 7, 2, 5, 2, armyCells, False):
        casted = lw_add(casted, 1)
    if tryPoisonCast(myID, CHIP_VENOM, 10, 0, 4, 1, armyCells, False):
        casted = lw_add(casted, 1)
    if (getStrength() >= 300):
        if tryPoisonCast(myID, CHIP_PLASMA, 6, 2, 9, 2, armyCells, False):
            casted = lw_add(casted, 1)
        casted = lw_add(casted, tryWeaponStrike(myID))
    if (casted == 0):
        if tryPoisonCast(myID, CHIP_VENOM, 10, 0, 4, 1, armyCells, True):
            casted = lw_add(casted, 1)
        else:
            if tryPoisonCast(myID, CHIP_TOXIN, 7, 2, 5, 2, armyCells, True):
                casted = lw_add(casted, 1)
            else:
                if tryPoisonCast(myID, CHIP_PLAGUE, 5, 3, 6, 2, armyCells, True):
                    casted = lw_add(casted, 1)
                else:
                    if ((getStrength() >= 300) and tryPoisonCast(myID, CHIP_PLASMA, 6, 2, 9, 2, armyCells, True)):
                        casted = lw_add(casted, 1)
        if (casted > 0):
            if tryPoisonCast(myID, CHIP_TOXIN, 7, 2, 5, 2, armyCells, False):
                casted = lw_add(casted, 1)
            if tryPoisonCast(myID, CHIP_PLAGUE, 5, 3, 6, 2, armyCells, False):
                casted = lw_add(casted, 1)
            if (getStrength() >= 300):
                casted = lw_add(casted, tryWeaponStrike(myID))
    if (casted > 0):
        say(lw_add("PZ POKE x", casted))
    else:
        say(lw_add(lw_add(lw_add(lw_add(lw_add("PZ POKE none d=", nearestArmyDistFrom(getCell(), armyCells)), " tp="), getTP()), " mp="), getMP()))
    swatCrystals(myID)
    nearestC = (-1)
    nearestPath = 9999
    for ac in lw_values(armyCells):
        pd = getPathLength(getCell(), ac)
        if ((pd != None) and (pd < nearestPath)):
            nearestPath = pd
            nearestC = ac
    approachGate = (9 if (casted > 0) else 6)
    if ((nearestC != (-1)) and (nearestPath > approachGate)):
        moveTowardCell(nearestC, min(getMP(), lw_sub(nearestPath, (lw_sub(approachGate, 1)))))
    else:
        kite = choosePuzzleSustainCellCapped(myID, getCell(), False, 9)
        if ((kite != (-1)) and (kite != getCell())):
            moveTowardCell(kite)
    return True

def tryWeaponStrike(myID):
    weps = getWeapons()
    if ((weps == None) or (not inArray(weps, WEAPON_ENHANCED_LIGHTNINGER))):
        return 0
    if (getWeapon() != WEAPON_ENHANCED_LIGHTNINGER):
        if (getTP() < 10):
            return 0
        setWeapon(WEAPON_ENHANCED_LIGHTNINGER)
    allies = getAliveAllies()
    n = 0
    while ((getTP() >= 9) and (n < 2)):
        myCell = getCell()
        enemies = getAliveEnemies()
        best = None
        bestD = 999
        for eid in lw_values(enemies):
            if (getName(eid) == "graal"):
                continue
            ec = getCell(eid)
            if ((ec == None) or (ec < 0)):
                continue
            dd = getCellDistance(myCell, ec)
            if (((dd == None) or (dd < 6)) or (dd > 10)):
                continue
            if (not lineOfSight(myCell, ec)):
                continue
            allyNear = False
            for aid in lw_values(allies):
                dA = getCellDistance(ec, getCell(aid))
                if ((dA != None) and (dA <= 1)):
                    allyNear = True
            if allyNear:
                continue
            if (dd < bestD):
                bestD = dd
                best = eid
        if (best == None):
            break
        if (useWeapon(best) < 1):
            break
        n = lw_add(n, 1)
    return n

def tryPoisonCast(myID, chip, rng, radius, cost, minCluster, armyCells, allowMove):
    if (not allyHasChip(myID, chip)):
        return False
    if (getTP() < cost):
        return False
    cd = getCooldown(chip, myID)
    if ((cd == None) or (cd > 0)):
        return False
    allies = getAliveAllies()
    myCell = getCell()
    bestAim = (-1)
    bestScore = (-99999)
    for aim in lw_values(armyCells):
        cluster = 0
        for ac in lw_values(armyCells):
            d = getCellDistance(aim, ac)
            if ((d != None) and (d <= radius)):
                cluster = lw_add(cluster, 1)
        if (cluster < minCluster):
            continue
        allyHit = False
        for aid in lw_values(allies):
            dA = getCellDistance(aim, getCell(aid))
            if ((dA != None) and (dA <= radius)):
                allyHit = True
        if allyHit:
            continue
        dMe2 = getCellDistance(myCell, aim)
        if (dMe2 == None):
            continue
        if (not allowMove):
            if (dMe2 > rng):
                continue
            if (not lineOfSight(myCell, aim)):
                continue
        sc = lw_sub(lw_mul(cluster, 100), dMe2)
        if (sc > bestScore):
            bestScore = sc
            bestAim = aim
    if (bestAim == (-1)):
        return False
    dAim = getCellDistance(myCell, bestAim)
    if (dAim == None):
        return False
    if ((dAim > rng) or (not lineOfSight(myCell, bestAim))):
        if (not allowMove):
            return False
        mp = getMP()
        if (mp <= 0):
            return False
        bestStand = (-1)
        bestStandScore = (-9999)
        c = 0
        while (c < 613):
            dMe = getCellDistance(myCell, c)
            if ((dMe == None) or (dMe > mp)):
                c = lw_add(c, 1)
                continue
            if ((c != myCell) and ((isObstacle(c) or isEntity(c)))):
                c = lw_add(c, 1)
                continue
            dC = getCellDistance(c, bestAim)
            if (((dC == None) or (dC < 1)) or (dC > rng)):
                c = lw_add(c, 1)
                continue
            pl = getPathLength(myCell, c)
            if ((pl == None) or (pl > mp)):
                c = lw_add(c, 1)
                continue
            if (not lineOfSight(c, bestAim)):
                c = lw_add(c, 1)
                continue
            sc2 = lw_sub(lw_mul(nearestArmyDistFrom(c, armyCells), 3), pl)
            if (sc2 > bestStandScore):
                bestStandScore = sc2
                bestStand = c
            c = lw_add(c, 1)
        if (bestStand == (-1)):
            return False
        moveTowardCell(bestStand)
        here = getCell()
        dNow = getCellDistance(here, bestAim)
        if (((dNow == None) or (dNow > rng)) or (not lineOfSight(here, bestAim))):
            return False
    return (useChipOnCell(chip, bestAim) >= 1)

