def peelAlignMove(myID, carryCell):
    mp = getMP()
    if (mp <= 0):
        return False
    myCell = getCell()
    enemies = getAliveEnemies()
    targets = []
    for eid in lw_values(enemies):
        n = getName(eid)
        if ((n == "graal") or (indexOf(n, "crystal") != (-1))):
            continue
        ec = getCell(eid)
        if ((ec == None) or (ec < 0)):
            continue
        dC = getCellDistance(ec, carryCell)
        push(targets, [(dC if (dC != None) else 99), ec])
    if (count(targets) == 0):
        return False
    used = {}
    nChecked = 0
    while (nChecked < 3):
        bi = (-1)
        bd = 9999
        i = 0
        while (i < count(targets)):
            if mapContainsKey(used, i):
                i = lw_add(i, 1)
                continue
            if (lw_get(lw_get(targets, i), 0) < bd):
                bd = lw_get(lw_get(targets, i), 0)
                bi = i
            i = lw_add(i, 1)
        if (bi == (-1)):
            break
        lw_put(used, bi, True)
        nChecked = lw_add(nChecked, 1)
        ec2 = lw_get(lw_get(targets, bi), 1)
        ex = getCellX(ec2)
        ey = getCellY(ec2)
        bestCell = (-1)
        bestPl = 999
        k = 2
        while (k <= 7):
            cands = [getCellFromXY(lw_add(ex, k), ey), getCellFromXY(lw_sub(ex, k), ey), getCellFromXY(ex, lw_add(ey, k)), getCellFromXY(ex, lw_sub(ey, k))]
            for c in lw_values(cands):
                if ((c == None) or (c < 0)):
                    continue
                if ((c != myCell) and ((isObstacle(c) or isEntity(c)))):
                    continue
                pl = getPathLength(myCell, c)
                if (((pl == None) or (pl > mp)) or (pl >= bestPl)):
                    continue
                if (not lineOfSight(c, ec2)):
                    continue
                bestPl = pl
                bestCell = c
            k = lw_add(k, 1)
        if (bestCell != (-1)):
            if (bestCell == myCell):
                return True
            moveTowardCell(bestCell)
            return (getCell() == bestCell)
    return False

def swatCrystals(myID):
    dmgChips = [CHIP_LIGHTNING, CHIP_ROCKFALL, CHIP_SPARK, CHIP_PEBBLE, CHIP_VENOM]
    enemies = getAliveEnemies()
    for eid in lw_values(enemies):
        if (indexOf(getName(eid), "crystal") == (-1)):
            continue
        for chip in lw_values(dmgChips):
            if (not allyHasChip(myID, chip)):
                continue
            cd = getCooldown(chip, myID)
            if ((cd == None) or (cd > 0)):
                continue
            if (getTP() < 5):
                continue
            if (useChip(chip, eid) >= 1):
                break

def peelPushOnce(myID, carryCell):
    myCell = getCell()
    enemies = getAliveEnemies()
    bestTarget = (-1)
    bestScore = (-9999)
    for eid in lw_values(enemies):
        n = getName(eid)
        if ((n == "graal") or (indexOf(n, "crystal") != (-1))):
            continue
        ec = getCell(eid)
        if ((ec == None) or (ec < 0)):
            continue
        if (not isOnSameLine(myCell, ec)):
            continue
        dMe = getCellDistance(myCell, ec)
        if (((dMe == None) or (dMe < 2)) or (dMe > 7)):
            continue
        if (not lineOfSight(myCell, ec)):
            continue
        dCarry = getCellDistance(ec, carryCell)
        score = lw_sub(100, lw_mul(((dCarry if (dCarry != None) else 20)), 5))
        if (score > bestScore):
            bestScore = score
            bestTarget = eid
    if (bestTarget == (-1)):
        return False
    ec2 = getCell(bestTarget)
    step = lineStepFromTo(myCell, ec2)
    if (step == 0):
        return False
    dest = ec2
    pos = ec2
    while True:
        nx = diagNext(pos, step)
        if (nx == (-1)):
            break
        if (isObstacle(nx) or isEntity(nx)):
            break
        if (getCellDistance(myCell, nx) > 8):
            break
        pos = nx
        dest = pos
    if (dest == ec2):
        return False
    return (useChipOnCell(CHIP_BOXING_GLOVE, dest) >= 1)

def lineStepFromTo(fromCell, toCell):
    fx = getCellX(fromCell)
    fy = getCellY(fromCell)
    tx = getCellX(toCell)
    ty = getCellY(toCell)
    if ((fy == ty) and (tx != fx)):
        return (18 if (tx > fx) else (-18))
    if ((fx == tx) and (ty != fy)):
        return (17 if (ty > fy) else (-17))
    return 0

def executePuzzleTurn():
    if (((_bossPhase != "PUZZLE") or (_graalCell == None)) or (_graalCell < 0)):
        return False
    if (_puzzleRole == "SOLVER"):
        return executeSolverPuzzleTurn()
    if (_puzzleRole == "BUFFER"):
        return executeBufferPuzzleTurn()
    if (_puzzleRole == "SUPPORT"):
        return executeSupportPuzzleTurn()
    return False

def findEmptyCellNear(targetCell, fromCell, maxRange, minDistToTarget):
    offsets = [0, 17, (-17), 18, (-18), 34, (-34), 35, (-35), 36, (-36), 1, (-1), 16, (-16), 19, (-19), 51, (-51), 52, (-52), 53, (-53), 54, (-54)]
    bestCell = (-1)
    bestDist = 999
    for off in lw_values(offsets):
        cell = lw_add(targetCell, off)
        if ((cell < 0) or (cell > 612)):
            continue
        if isObstacle(cell):
            continue
        if ((cell != fromCell) and isEntity(cell)):
            continue
        dFrom = getCellDistance(fromCell, cell)
        if (((dFrom == None) or (dFrom < 1)) or (dFrom > maxRange)):
            continue
        dTo = getCellDistance(cell, targetCell)
        if ((dTo == None) or (dTo < minDistToTarget)):
            continue
        if (dTo < bestDist):
            bestDist = dTo
            bestCell = cell
    return bestCell

def puzzleGatherMove(gathererID, targetSolverCell):
    walkDist = getCellDistance(getCell(), targetSolverCell)
    if ((walkDist != None) and (walkDist > 2)):
        moveTowardCell(targetSolverCell, min(getMP(), lw_sub(walkDist, 2)))
    gatherCell = getCell()
    gatherDist = getCellDistance(gatherCell, targetSolverCell)
    if ((gatherDist > 5) and (getTurn() >= 2)):
        gTpCd = getCooldown(CHIP_TELEPORTATION, gathererID)
        if (((gTpCd != None) and (gTpCd == 0)) and (getTP() >= 9)):
            tpCell = findEmptyCellNear(targetSolverCell, gatherCell, 12, 2)
            if (tpCell != (-1)):
                useChipOnCell(CHIP_TELEPORTATION, tpCell)

