def isPuzzleWorkZone(cell):
    if (_graalCell == (-1)):
        return False
    dG = getCellDistance(cell, _graalCell)
    if ((dG != None) and (dG <= 4)):
        return True
    cx = getCellX(cell)
    cy = getCellY(cell)
    if (((((cx == _graalX) or (cy == _graalY))) and (dG != None)) and (dG <= 9)):
        return True
    for eid in lw_values(mapKeys(_crystalMap)):
        cc = getCell(eid)
        if ((cc == None) or (cc < 0)):
            continue
        dC = getCellDistance(cell, cc)
        if ((dC != None) and (dC <= 1)):
            return True
    return False

def puzzleSelfPreserve(myID, leashed):
    selfShields = [[CHIP_FORTRESS, 6], [CHIP_ARMOR, 6], [CHIP_WALL, 3]]
    for sh in lw_values(selfShields):
        chip = lw_get(sh, 0)
        cost = lw_get(sh, 1)
        if (not allyHasChip(myID, chip)):
            continue
        if (getTP() < cost):
            continue
        cd = getCooldown(chip, myID)
        if ((cd != None) and (cd == 0)):
            useChip(chip, myID)
    if (((entityHPPercent(myID) < 40) and allyHasChip(myID, CHIP_REGENERATION)) and (getTP() >= 8)):
        rcd = getCooldown(CHIP_REGENERATION, myID)
        if ((rcd != None) and (rcd == 0)):
            useChip(CHIP_REGENERATION, myID)
    solverAlive = ((_puzzleSolverID != (-1)) and isAlive(_puzzleSolverID))
    anchorCell = (getCell(_puzzleSolverID) if solverAlive else getCell())
    distToSolver = getCellDistance(getCell(), anchorCell)
    if ((leashed and solverAlive) and (distToSolver > 8)):
        tpCd = getCooldown(CHIP_TELEPORTATION, myID)
        if (((tpCd != None) and (tpCd == 0)) and (getTP() >= 9)):
            tc = findEmptyCellNear(anchorCell, getCell(), 12, 2)
            if ((tc != (-1)) and (not isPuzzleWorkZone(tc))):
                useChipOnCell(CHIP_TELEPORTATION, tc)
        followDist = getCellDistance(getCell(), anchorCell)
        if ((followDist != None) and (followDist > 2)):
            moveTowardCell(anchorCell, min(getMP(), lw_sub(followDist, 2)))
        return None
    best = choosePuzzleSustainCell(myID, anchorCell, (leashed and solverAlive))
    if ((best != (-1)) and (best != getCell())):
        moveTowardCell(best)

def choosePuzzleSustainCell(myID, anchorCell, leashed):
    return choosePuzzleSustainCellCapped(myID, anchorCell, leashed, 12)

def choosePuzzleSustainCellCapped(myID, anchorCell, leashed, armyCap):
    mp = getMP()
    if (mp <= 0):
        return (-1)
    myCell = getCell()
    armyCells = puzzleArmyCells()
    allies = getAliveAllies()
    best = (-1)
    bestScore = (-99999)
    c = 0
    while (c < 613):
        dMe = getCellDistance(myCell, c)
        if ((dMe == None) or (dMe > mp)):
            c = lw_add(c, 1)
            continue
        if ((c != myCell) and ((isObstacle(c) or isEntity(c)))):
            c = lw_add(c, 1)
            continue
        if (c != myCell):
            pl = getPathLength(myCell, c)
            if ((pl == None) or (pl > mp)):
                c = lw_add(c, 1)
                continue
        score = lw_mul(min(nearestArmyDistFrom(c, armyCells), armyCap), 14)
        if isPuzzleWorkZone(c):
            score = lw_num(score) - lw_num(80)
        if leashed:
            dS = getCellDistance(c, anchorCell)
            if ((dS != None) and (dS > 3)):
                score = lw_num(score) - lw_num(lw_mul((lw_sub(dS, 3)), 12))
            if ((dS != None) and (dS < 2)):
                score = lw_num(score) - lw_num(40)
        for aid in lw_values(allies):
            if (aid == _puzzleSolverID):
                continue
            dA = getCellDistance(c, getCell(aid))
            if ((dA != None) and (dA < 2)):
                score = lw_num(score) - lw_num(25)
        if (score > bestScore):
            bestScore = score
            best = c
        c = lw_add(c, 1)
    return best

def executeSupportPuzzleTurn():
    myID = getEntity()
    if (getStrength() >= 300):
        if (((getTurn() == 1) and (_puzzleSolverID != (-1))) and isAlive(_puzzleSolverID)):
            farBuffs = [[CHIP_ELEVATION, 5, 6, "elev"], [CHIP_LEATHER_BOOTS, 5, 3, "boots"]]
            castBuffsOnSolver(myID, farBuffs)
        puzzleSelfPreserve(myID, False)
        return True
    if ((_puzzleSolverID == (-1)) or (not isAlive(_puzzleSolverID))):
        say("PZ SUPPORT: no solver")
        puzzleSelfPreserve(myID, False)
        return True
    solverCell = getCell(_puzzleSolverID)
    dist = getCellDistance(getCell(), solverCell)
    if (((getTurn() <= 2) and (dist > 3)) and hasPendingSolverHPBuff(myID)):
        puzzleGatherMove(myID, solverCell)
    buffs = [[CHIP_ELEVATION, 5, 6, "elev"], [CHIP_ARMORING, 3, 5, "armor"], [CHIP_LEATHER_BOOTS, 5, 3, "boots"], [CHIP_ADRENALINE, 3, 1, "adren"]]
    castBuffsOnSolver(myID, buffs)
    puzzleSustainSolver(myID)
    puzzleSelfPreserve(myID, (getTurn() <= 2))
    return True

def executeSolverPuzzleTurn():
    global _bossTargetEID, _myAssignedCrystal, _pzGatherDone, _pzRouteChip, _pzRouteCrystalCell, _pzRouteEID, _pzRouteStand, _pzRouteTarget, _pzSolverMaxLifeSnapshot
    if (getTurn() == 1):
        allA = []
        push(allA, getEntity())
        als = getAliveAllies()
        for a in lw_values(als):
            push(allA, a)
        sort(allA)
        if (lw_get(allA, 0) == getEntity()):
            logMapLayout()
    myCell = getCell()
    myID = getEntity()
    maxLifeNow = getTotalLife(myID)
    lifeGain = (maxLifeNow if (_pzSolverMaxLifeSnapshot == (-1)) else lw_sub(maxLifeNow, _pzSolverMaxLifeSnapshot))
    if ((not _pzGatherDone) and (((getTurn() <= 2) or (((getTurn() <= 3) and (lifeGain >= 400)))))):
        say(lw_add(lw_add(lw_add(lw_add("PZ SOLVER: waiting for ally buffs (turn ", getTurn()), ", maxHP "), maxLifeNow), ")"))
        solverSelfBuff(myID)
        waitArmy = puzzleArmyCells()
        if ((count(waitArmy) > 0) and (nearestArmyDistFrom(getCell(), waitArmy) <= 12)):
            waitKite = choosePuzzleSustainCellCapped(myID, getCell(), False, 12)
            if ((waitKite != (-1)) and (waitKite != getCell())):
                moveTowardCell(waitKite, min(getMP(), 3))
        _pzSolverMaxLifeSnapshot = getTotalLife(myID)
        return True
    _pzGatherDone = True
    solverSurvival(myID)
    firstEID = pickFocusCrystal(myCell)
    if (firstEID == None):
        say("PZ SOLVER: all done")
        solverSelfBuff(myID)
        return True
    _bossTargetEID = firstEID
    syncCrystalScalars(lw_get(_crystalMap, firstEID))
    firstDest = computeCrystalFinalDest()
    crystalCell0 = getCell(firstEID)
    if ((crystalCell0 != None) and (crystalCell0 >= 0)):
        tpCd = getCooldown(CHIP_TELEPORTATION, myID)
        if ((((tpCd != None) and (tpCd == 0)) and (getTP() >= 12)) and (firstDest != None)):
            tpDone = False
            preMove = planCrystalRoute(crystalCell0, _myCrystalGoalAxis, myCell, False)
            if (preMove == None):
                preMove = findBestChipMove(crystalCell0, firstDest, myCell, 0, 0, 0)
            if (preMove != None):
                preStand = lw_get(preMove, 'stand')
                dToStand = getCellDistance(myCell, preStand)
                if ((dToStand >= 1) and (dToStand <= 12)):
                    if (useChipOnCell(CHIP_TELEPORTATION, preStand) == 1):
                        myCell = getCell()
                        tpDone = True
            if (not tpDone):
                tpTarget = findTeleportTarget(crystalCell0, myCell)
                if (tpTarget != (-1)):
                    if (useChipOnCell(CHIP_TELEPORTATION, tpTarget) == 1):
                        myCell = getCell()
                        tpDone = True
            if (not tpDone):
                nearest = findNearestEnclaveCell(myCell)
                if (nearest != (-1)):
                    moveTowardCell(nearest)
                    myCell = getCell()
                    tpTarget2 = findTeleportTarget(crystalCell0, myCell)
                    if (tpTarget2 != (-1)):
                        if (useChipOnCell(CHIP_TELEPORTATION, tpTarget2) == 1):
                            myCell = getCell()
                solverSelfBuff(myID)
                return True
        else:
            if ((tpCd != None) and (tpCd > 0)):
                dToCrystal = getCellDistance(myCell, crystalCell0)
                if (dToCrystal > 10):
                    say(lw_add(lw_add(lw_add("PZ SOLVER: closing on c=", firstEID), " d="), dToCrystal))
                    moveTowardCell(crystalCell0)
                    solverSelfBuff(myID)
                    return True
    bootsCd = getCooldown(CHIP_LEATHER_BOOTS, myID)
    if (((bootsCd != None) and (bootsCd == 0)) and (getTP() >= 4)):
        useChip(CHIP_LEATHER_BOOTS, myID)
    adrenCd = getCooldown(CHIP_ADRENALINE, myID)
    if (((adrenCd != None) and (adrenCd == 0)) and (getTP() >= 1)):
        useChip(CHIP_ADRENALINE, myID)
    totalChipsFired = 0
    crystalsSolved = 0
    while (getTP() >= 3):
        myCell = getCell()
        nextEID = pickFocusCrystal(myCell)
        if (nextEID == None):
            say(lw_add(lw_add("PZ SOLVER: ALL DONE (", crystalsSolved), " this turn)"))
            break
        _bossTargetEID = nextEID
        _myAssignedCrystal = lw_get(_crystalMap, nextEID)
        syncCrystalScalars(lw_get(_crystalMap, nextEID))
        finalDest = computeCrystalFinalDest()
        if (finalDest == None):
            say(lw_add("PZ: no dest for ", nextEID))
            moveTowardCell(lw_get(lw_get(_crystalMap, nextEID), 'cell'))
            return True
        grapUsed = 0
        boxUsed = 0
        chipsFired = 0
        lockedStep = 0
        detourCount = 0
        while (chipsFired < 8):
            crystalCell = getCell(_bossTargetEID)
            if ((crystalCell == None) or (crystalCell < 0)):
                break
            if isCellSolvedForAxis(crystalCell, _myCrystalGoalAxis):
                break
            if (getTP() < 3):
                break
            myCell = getCell()
            invCd = getCooldown(CHIP_INVERSION, myID)
            invReady = (((allyHasChip(myID, CHIP_INVERSION) and (invCd != None)) and (invCd == 0)) and (getTP() >= 4))
            move = None
            if (((_pzRouteEID == _bossTargetEID) and (_pzRouteCrystalCell == crystalCell)) and (_pzRouteStand != (-1))):
                standFree = ((_pzRouteStand == myCell) or (((not isObstacle(_pzRouteStand)) and (not isEntity(_pzRouteStand)))))
                chipOk = ((_pzRouteChip != CHIP_INVERSION) or invReady)
                if (standFree and chipOk):
                    move = {'stand': _pzRouteStand, 'chip': _pzRouteChip, 'target': _pzRouteTarget}
            if (move == None):
                move = planCrystalRoute(crystalCell, _myCrystalGoalAxis, myCell, invReady)
            if (move == None):
                move = findBestChipMove(crystalCell, finalDest, myCell, grapUsed, boxUsed, lockedStep)
            if (move == None):
                if (detourCount < 4):
                    move = findDetourMove(crystalCell, finalDest, myCell, grapUsed, boxUsed, lockedStep)
                    if (move != None):
                        detourCount = lw_add(detourCount, 1)
            if (move == None):
                break
            _pzRouteEID = _bossTargetEID
            _pzRouteCrystalCell = crystalCell
            _pzRouteStand = lw_get(move, 'stand')
            _pzRouteChip = lw_get(move, 'chip')
            _pzRouteTarget = lw_get(move, 'target')
            stand = lw_get(move, 'stand')
            chip = lw_get(move, 'chip')
            target = lw_get(move, 'target')
            if (myCell != stand):
                if (getMP() == 0):
                    break
                prevCell = myCell
                moveTowardCell(stand)
                myCell = getCell()
                if (myCell == prevCell):
                    _pzRouteEID = None
                    break
                if (myCell != stand):
                    break
            if (chip == CHIP_INVERSION):
                invR = useChip(CHIP_INVERSION, _bossTargetEID)
                if (invR < 1):
                    debug(lw_add(lw_add(lw_add(lw_add(lw_add("PZDBG inv fail r=", invR), " me="), myCell), " cr="), crystalCell))
                    _pzRouteEID = None
                    break
                myCell = getCell()
                chipsFired = lw_add(chipsFired, 1)
                totalChipsFired = lw_add(totalChipsFired, 1)
                say(lw_add("PZ INV c=", _bossTargetEID))
                continue
            if (not lineOfSight(myCell, crystalCell)):
                debug(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add("PZDBG los-block me=", myCell), " cr="), crystalCell), " chip="), chip), " tgt="), target))
                _pzRouteEID = None
                break
            r = useChipOnCell(chip, target)
            if (r < 1):
                debug(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add(lw_add("PZDBG cast fail r=", r), " chip="), chip), " me="), myCell), " tgt="), target), " cr="), crystalCell))
                _pzRouteEID = None
                break
            chipsFired = lw_add(chipsFired, 1)
            totalChipsFired = lw_add(totalChipsFired, 1)
            if (chip == CHIP_GRAPPLE):
                grapUsed = lw_add(grapUsed, 1)
            else:
                boxUsed = lw_add(boxUsed, 1)
            if (((lockedStep == 0) and mapContainsKey(move, 'score')) and (lw_get(move, 'score') > 0)):
                firedStep = lw_get(move, 'step')
                lockedStep = (-lw_num(firedStep))
        crCell = getCell(_bossTargetEID)
        solved = isCellSolvedForAxis(crCell, _myCrystalGoalAxis)
        if solved:
            crystalsSolved = lw_add(crystalsSolved, 1)
            say(lw_add(lw_add(lw_add(lw_add(lw_add("PZ DONE c=", _bossTargetEID), " f="), chipsFired), " total="), crystalsSolved))
            continue
        else:
            say(lw_add(lw_add(lw_add(lw_add(lw_add("PZ f=", chipsFired), " cr="), crCell), " dst="), finalDest))
            if (((chipsFired > 0) and (crCell != None)) and (crCell >= 0)):
                moveTowardCell(crCell)
            else:
                if (chipsFired == 0):
                    crystalNow = getCell(_bossTargetEID)
                    if (((crystalNow != None) and (crystalNow >= 0)) and (getCellDistance(getCell(), crystalNow) <= 1)):
                        moveTowardCell(finalDest)
                    else:
                        if ((crystalNow != None) and (crystalNow >= 0)):
                            moveTowardCell(crystalNow)
            break
    solverSelfBuff(myID)
    return True

def getBossPuzzleTarget(fieldMapObj):
    if (_bossTargetEID == None):
        return None
    enemySub = fieldMapObj.getEnemySubMap()
    if mapContainsKey(enemySub, _bossTargetEID):
        return lw_get(enemySub, _bossTargetEID)
    if mapContainsKey(fieldMapObj.entities, _bossTargetEID):
        return lw_get(fieldMapObj.entities, _bossTargetEID)
    if (_myCrystalCell != (-1)):
        return Enemy(_myCrystalCell)
    return None


# ════════ action.lk ════════
class Action:
    NONE = (-1)
    ACTION_DIRECT = 0
    ACTION_DOT = 1
    ACTION_DEBUFF = 2
    ACTION_BUFF = 3
    ACTION_WEAPON_SWAP = 4
    MOVEMENT_APPROACH = 5
    MOVEMENT_OFFENSIVE = 6
    MOVEMENT_DEFENSIVE = 7
    MOVEMENT_OTKO = 8
    MOVEMENT_DOT_OFFENSIVE = 9
    MOVEMENT_DEBUFF = 10
    MOVEMENT_FLEE = 11
    MOVEMENT_HNS = 12
    MOVEMENT_PAB = 13
    ACTION_TELEPORT = 14
    ACTION_CHECKPOINT = 15
    ACTION_SUMMON = 16
    def __init__(self, type, weaponId, chip, targetCell, targetEntity):
        self.type = (-1)
        self.weaponId = (-1)
        self.chip = (-1)
        self.targetCell = (-1)
        self.targetEntity = (-1)
        self.isSplash = False
        self.weapon = None
        self.checkpointType = ""
        self.continuationFn = ""
        self.context = None
        self.bulbAIFunc = None
        self.type = type
        self.weaponId = weaponId
        self.chip = chip
        self.targetCell = targetCell
        self.targetEntity = targetEntity

    @staticmethod
    def createCheckpoint(checkpointType, continuationFn, context):
        checkpoint = Action(Action.ACTION_CHECKPOINT, (-1), (-1), (-1), None)
        checkpoint.checkpointType = checkpointType
        checkpoint.continuationFn = continuationFn
        checkpoint.context = context
        return checkpoint
    


# ════════ bulb_ai.lk ════════
def savantBulbAI():
    me = getEntity()
    summoner = getSummoner()
    myCell = getCell()
    summonerCell = getCell(summoner)
    myTP = getTP()
    distToSummoner = getCellDistance(myCell, summonerCell)
    if (distToSummoner > 3):
        moveToward(summoner)
        myCell = getCell()
    if ((myTP >= 1) and (getCooldown(CHIP_ADRENALINE, me) == 0)):
        summonerTP = getTP(summoner)
        if (summonerTP < 10):
            dist = getCellDistance(myCell, summonerCell)
            if ((((dist != None) and (dist >= 0)) and (dist <= 3)) and lineOfSight(myCell, summonerCell)):
                useChip(CHIP_ADRENALINE, summoner)
                myTP = getTP()
    if ((myTP >= 7) and (getCooldown(CHIP_MUTATION, me) == 0)):
        dist = getCellDistance(myCell, summonerCell)
        if ((((dist != None) and (dist >= 0)) and (dist <= 8)) and lineOfSight(myCell, summonerCell)):
            useChip(CHIP_MUTATION, summoner)
            myTP = getTP()
    if ((myTP >= 3) and (getCooldown(CHIP_ALTERATION, me) == 0)):
        enemies = getAliveEnemies()
        bestTarget = None
        bestHP = 999999
        for eid in lw_values(enemies):
            if isDead(eid):
                continue
            enemyCell = getCell(eid)
            dist = getCellDistance(myCell, enemyCell)
            if ((((dist != None) and (dist >= 6)) and (dist <= 12)) and lineOfSight(myCell, enemyCell)):
                hp = getLife(eid)
                if (hp < bestHP):
                    bestHP = hp
                    bestTarget = eid
        if (bestTarget != None):
            useChip(CHIP_ALTERATION, bestTarget)
            myTP = getTP()
    if ((myTP >= 4) and (getCooldown(CHIP_THORN, me) == 0)):
        enemies = getAliveEnemies()
        nearbyEnemy = False
        for eid in lw_values(enemies):
            if isDead(eid):
                continue
            dist = getCellDistance(myCell, getCell(eid))
            if ((dist != None) and (dist <= 5)):
                nearbyEnemy = True
                break
        if nearbyEnemy:
            useChip(CHIP_THORN, me)
            myTP = getTP()

