_ops64 = 9000000
_ops71 = 10000000
_ops79 = 11000000
_ops82 = 11500000
_ops86 = 12000000
_ops89 = 12500000
_ops93 = 13000000
_ops96 = 13500000
_beamWidth = 20
_beamMaxDepth = 10
_mutationMaxSeeds = 6
_mutationMaxPerSeed = 80
_twoplyTopK = 5
_enemyLookaheadTopK = 8
_beamMaxDepthBase = 10
_mutationMaxSeedsBase = 6
_mutationMaxPerSeedBase = 80
_beamWidthBase = 20
